1: //! Certain implementations of Forth naively and eagerly expand sub-definitions
2: //! into superior definitions at definition time. While this appears at first to
3: //! be a clever trick to solve the problem imposed by the
4: //! `can_use_different_words_with_the_same_name` test, it has its own problem: it
5: //! can be attacked to cause an OOM condition in an arbitrary machine without
6: //! requiring that any instructions are actually executed; only definitions.
7: //!
8: //! This test doesn't go quite that far, but it does demonstrate the attack and
9: //! require that implementations don't just do the naive thing.
10: 
11: use forth::Forth;
12: 
13: #[test]
14: #[ignore]
15: fn alloc_attack() {
16:     let mut f = Forth::new();
17:     f.eval(": a 0 drop ;").unwrap();
18:     f.eval(": b a a ;").unwrap();
19:     f.eval(": c b b ;").unwrap();
20:     f.eval(": d c c ;").unwrap();
21:     f.eval(": e d d ;").unwrap();
22:     f.eval(": f e e ;").unwrap();
23:     f.eval(": g f f ;").unwrap();
24:     f.eval(": h g g ;").unwrap();
25:     f.eval(": i h h ;").unwrap();
26:     f.eval(": j i i ;").unwrap();
27:     f.eval(": k j j ;").unwrap();
28:     f.eval(": l k k ;").unwrap();
29:     f.eval(": m l l ;").unwrap();
30:     f.eval(": n m m ;").unwrap();
31:     f.eval(": o n n ;").unwrap();
32:     f.eval(": p o o ;").unwrap();
33:     f.eval(": q p p ;").unwrap();
34:     f.eval(": r q q ;").unwrap();
35:     f.eval(": s r r ;").unwrap();
36:     f.eval(": t s s ;").unwrap();
37:     f.eval(": u t t ;").unwrap();
38:     f.eval(": v u u ;").unwrap();
39:     f.eval(": w v v ;").unwrap();
40:     f.eval(": x w w ;").unwrap();
41:     f.eval(": y x x ;").unwrap();
42:     f.eval(": z y y ;").unwrap();
43: 
44:     // On an implementation with eager expansion of sub-custom-words,
45:     // `z`'s definition is 2**26 items long. Assuming the implementation
46:     // has compacted each instruction into a single byte, that takes up
47:     // over 50 Mb of memory. Less efficient implementations will require
48:     // more.
49:     //
50:     // This shouldn't crash or hang anyone's machine, but it's at least a
51:     // testable proposition. A good implementation shouldn't be doing eager
52:     // stack expansion, so it should require much less than that.
53: 
54:     // Sanity check--few implementations should fail here.
55:     assert!(f.stack().is_empty());
56: 
57:     // We want to allow some wiggle-room, as this exercise isn't really meant
58:     // to test the ability to micro-optimize. Still, let's ensure that the total
59:     // allocated memory is substantially less than expected from a naive solution.
60:     //
61:     // A megabyte seems like a reasonable number to use.
62:     assert!(GLOBAL_ALLOCATOR.get_bytes_allocated() < 1024 * 1024);
63: }
